    stmt = markClangAstObjectDefined(stmt);
    markClangDeclObjectDefinedByKind(stmt->getExceptionDecl());
    markClangStmtObjectDefinedByClass(
        markClangAstObjectDefined(stmt->getHandlerBlock()));
